"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["62626"],{19735(e){e.exports=JSON.parse('{"id":"V4-107","slug":"investment-grade","term":"Investment Grade","also_known_as":[],"difficulty":"Intermediate","definition":"Investment grade is a credit rating category for bonds and borrowers considered to have a relatively low risk of default, defined as BBB- or higher by S&P and Fitch, or Baa3 or higher by Moody\u2019s.","explanation":["Credit rating agencies divide ratings into two broad groups. Investment-grade ratings, from AAA down to BBB-, indicate stronger ability to repay. Ratings below this level are called high yield or speculative grade.","The distinction has important practical effects. Many pension funds, insurers and other institutional investors are restricted by their rules or regulations to holding mainly investment-grade bonds. Investment-grade issuers can usually borrow at lower interest rates.","For example, a large, stable utility company rated A might borrow at only slightly more than the government, while a company rated BB would pay considerably more.","When a company is downgraded from investment grade to high yield, it becomes a fallen angel, and some investors may be forced to sell its bonds, which can push prices down sharply. Companies rated BBB, at the lowest level of investment grade, are watched closely for this risk. Investment grade does not mean risk-free, and investment-grade issuers can still default, although this is rare."],"note":"","total":1725,"prev":{"slug":"investment-bank","term":"Investment Bank"},"next":{"slug":"investment-horizon","term":"Investment Horizon"}}')}}]);